272	func configureRepoIdentity(ctx context.Context) (owner, repo, cleanRemote string, err error) {
273		raw, err := gitremote.GetRemoteURL(ctx, defaultMirrorRemote)
274		if err != nil {
275			return "", "", "", fmt.Errorf("read origin remote: %w", err)
276		}
277		info, err := gitremote.ParseURL(raw)
278		if err != nil {
279			return "", "", "", fmt.Errorf("parse origin remote: %w", err)
280		}
281		if info.Forge != mirrorUseForge {
282			return "", "", "", errors.New("interactive configure currently requires a GitHub origin remote")
283		}
284		clean, err := cleanRemoteURLForReport(raw)
285		if err != nil {
286			return "", "", "", err
287		}
288		return strings.ToLower(info.Owner), strings.ToLower(info.Repo), clean, nil
289	}
