291	func ensureConfigureLogin(ctx context.Context, outW, errW io.Writer, deps configureFlowDeps) (*authProfile, error) {
292		target, err := deps.resolveAuth(ctx)
293		if err != nil {
294			return nil, err
295		}
296		if target.token != "" {
297			if err := api.RequireSecureURL(target.coreURL); err != nil {
298				return nil, fmt.Errorf("context login server URL check: %w", err)
299			}
300			if profile, profileErr := deps.fetchProfile(ctx, target.coreURL, target.token); profileErr == nil {
301				return profile, nil
302			} else if !isKeychainTokenRejected(profileErr) {
303				return nil, fmt.Errorf("validate login: %w", profileErr)
304			}
305		}
306	
307		if err := deps.runLogin(ctx, outW, errW); err != nil {
308			return nil, fmt.Errorf("login: %w", err)
309		}
310		target, err = deps.resolveAuth(ctx)
311		if err != nil {
312			return nil, err
313		}
314		if target.token == "" {
315			return nil, errors.New("login completed without an active session")
316		}
317		if err := api.RequireSecureURL(target.coreURL); err != nil {
318			return nil, fmt.Errorf("context login server URL check: %w", err)
319		}
320		profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
321		if err != nil {
322			return nil, fmt.Errorf("validate login: %w", err)
323		}
324		fmt.Fprintf(outW, "✓ Logged in as %s\n", profile.Handle)
325		return profile, nil
326	}
