328	func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, nonInteractive bool, deps configureFlowDeps) error {
329		fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
330		installURL := strings.TrimSpace(initial.InstallURL)
331		if installURL == "" {
332			installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
333		}
334	
335		admin, adminErr := deps.githubAdmin(ctx, owner, repo)
336		if adminErr == nil && !admin {
337			fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
338			fmt.Fprintln(errW, "  Send them this link to continue:")
339			fmt.Fprintf(errW, "\n  %s\n", installURL)
340			return NewSilentError(errors.New("GitHub app installation required"))
341		}
342		if adminErr != nil {
343			switch {
344			case errors.Is(adminErr, errConfigureGHUnavailable):
345				fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not installed.")
346				fmt.Fprintln(errW, "  Install it from https://cli.github.com/ and run `gh auth login` for future checks.")
347			case errors.Is(adminErr, errConfigureGHUnauthenticated):
348				fmt.Fprintln(errW, "  Could not verify GitHub admin access because the gh CLI is not authenticated.")
349				fmt.Fprintln(errW, "  Run `gh auth login` for future checks.")
350			default:
351				fmt.Fprintf(errW, "  Could not verify GitHub admin access: %v\n", adminErr)
352			}
353			fmt.Fprintln(errW, "  If you administer this repository, you can still continue with the installation link.")
354			fmt.Fprintln(errW)
355		}
356	
357		fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
358		fmt.Fprintf(outW, "  %s\n\n", installURL)
359		if nonInteractive {
360			return NewSilentError(errors.New("GitHub app installation required; install it with the URL above, then rerun 'entire configure --yes'"))
361		}
362		if err := deps.openURL(ctx, installURL); err != nil {
363			fmt.Fprintln(outW, "  Open the link above in your browser.")
364		}
365		stop := startSpinner(errW, "Waiting for installation")
366		stopped := false
367		defer func() {
368			if !stopped {
369				stop(false)
370			}
371		}()
372	
373		waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
374		defer cancel()
375		ticker := time.NewTicker(configureAccessPollInterval)
376		defer ticker.Stop()
377		for {
378			select {
379			case <-waitCtx.Done():
380				return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
381			case <-ticker.C:
382				access, err := reporter.ReportEnable(waitCtx, cleanRemote)
383				if err == nil && access.Connected {
384					stop(true)
385					stopped = true
386					fmt.Fprintln(outW, "✓ Access granted")
387					return nil
388				}
389			}
390		}
391	}
