412	func configureCreateMirrors(ctx context.Context, outW, errW io.Writer, client *coreapi.Client, owner, repo, jurisdiction string, nonInteractive bool) ([]coreapi.ResolvedPlacement, error) {
413		regions, err := availableRegions(ctx, client)
414		if err != nil {
415			return nil, fmt.Errorf("list regions: %w", err)
416		}
417		if len(regions) == 0 {
418			return nil, errors.New("no regions available to mirror into")
419		}
420		selected, err := pickConfigureRegions(ctx, outW, regions, jurisdiction, nonInteractive)
421		if err != nil {
422			return nil, err
423		}
424		results := createMirrors(ctx, errW, mirrorTargets([]coreapi.AvailableMirror{{Owner: owner, Repo: repo}}, selected), false, 30*time.Minute)
425		reportErr := reportMirrorResults(outW, errW, results)
426		placements := configureSuccessfulMirrorPlacements(selected, results)
427		if len(placements) > 0 {
428			if reportErr != nil {
429				fmt.Fprintf(errW, "Continuing with %d mirror(s) that succeeded.\n", len(placements))
430			}
431			return placements, nil
432		}
433		if reportErr != nil {
434			return nil, reportErr
435		}
436		return nil, errors.New("no usable mirrors were created")
437	}
