455	func pickConfigureRegions(ctx context.Context, outW io.Writer, regions []regionChoice, jurisdiction string, nonInteractive bool) ([]regionChoice, error) {
456		opts, defaults := clusterChoices(regions, jurisdiction)
457		byHost := make(map[string]regionChoice, len(regions))
458		for _, region := range regions {
459			byHost[region.host] = region
460		}
461		selected := append([]string(nil), defaults...)
462		if nonInteractive {
463			if len(selected) == 0 && len(opts) > 0 {
464				selected = append(selected, opts[0].Value)
465			}
466			chosen := make([]regionChoice, 0, len(selected))
467			for _, host := range selected {
468				if region, ok := byHost[host]; ok {
469					chosen = append(chosen, region)
470				}
471			}
472			return chosen, nil
473		}
474		form := NewAccessibleForm(huh.NewGroup(
475			huh.NewMultiSelect[string]().
476				Title("Which regions should this repository live in?").
477				Description("Space to select, enter to confirm — your data stays in the selected regions.").
478				Options(opts...).
479				Height(multiSelectHeight(len(opts))).
480				Validate(func(values []string) error {
481					if len(values) == 0 {
482						return errors.New("select at least one region")
483					}
484					return nil
485				}).
486				Value(&selected),
487		))
488		if err := form.RunWithContext(ctx); err != nil {
489			if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
490				return nil, cancelErr
491			}
492			return nil, NewSilentError(errors.New("configure cancelled"))
493		}
494		chosen := make([]regionChoice, 0, len(selected))
495		for _, host := range selected {
496			if region, ok := byHost[host]; ok {
497				chosen = append(chosen, region)
498			}
499		}
500		return chosen, nil
501	}
