503	// configureFocusChangedMsg forces huh's dynamic titles to re-evaluate after a
504	// field transition. huh evaluates TitleFunc before it calls Blur/Focus while
505	// handling NextField, so without this follow-up frame the help bar changes but
506	// the old section keeps the active-colored question mark until another keypress.
507	type configureFocusChangedMsg struct{}
508	
509	func configureRefreshFocus() tea.Cmd {
510		return func() tea.Msg { return configureFocusChangedMsg{} }
511	}
512	
513	type configureUpstreamField struct {
514		*huh.Select[string]
515	
516		value         *string
517		committed     string
518		highlighted   string
519		refresh       func()
520		layoutChanged func()
521		window        tea.WindowSizeMsg
522		focused       bool
523	}
524	
525	func (field *configureUpstreamField) Focus() tea.Cmd {
526		field.focused = true
527		return tea.Batch(field.Select.Focus(), configureRefreshFocus())
528	}
529	
530	func (field *configureUpstreamField) Blur() tea.Cmd {
531		field.focused = false
532		return field.Select.Blur()
533	}
534	
535	func (field *configureUpstreamField) KeyBinds() []key.Binding {
536		return configureRadioKeyBinds(field.Select)
537	}
538	
539	func (field *configureUpstreamField) View() string {
540		return field.Select.View() + "\n\n"
541	}
542	
543	func (field *configureUpstreamField) Update(msg tea.Msg) (huh.Model, tea.Cmd) {
544		if keyMsg, ok := msg.(tea.KeyPressMsg); ok {
545			switch {
546			case configureRadioSelectKey(keyMsg.String()):
547				field.commitHighlighted()
548				return field, configureWindowResize(field.window)
549			case configureNextKey(keyMsg.String()):
550				// Enter continues with the intentionally selected value. Merely moving
551				// the cursor does not change the radio selection.
552				return field, huh.NextField
553			}
554		}
555		if size, ok := msg.(tea.WindowSizeMsg); ok {
556			field.window = size
557		}
558		model, cmd := field.Select.Update(msg)
559		if updated, ok := model.(*huh.Select[string]); ok {
560			field.Select = updated
561		}
562		_, movedCursor := msg.(tea.KeyPressMsg)
563		field.preserveCommittedSelection(movedCursor)
564		return field, cmd
565	}
566	
567	func (field *configureUpstreamField) preserveCommittedSelection(movedCursor bool) {
568		if field.value == nil {
569			return
570		}
571		if movedCursor {
572			field.highlighted = *field.value
573		}
574		*field.value = field.committed
575	}
576	
577	func (field *configureUpstreamField) commitHighlighted() {
578		if field.value == nil {
579			return
580		}
581		field.committed = field.highlighted
582		*field.value = field.committed
583		if field.refresh != nil {
584			field.refresh()
585		}
586		if field.layoutChanged != nil {
587			field.layoutChanged()
588		}
589	}
