671	func sameStrings(a, b []string) bool {
672		if len(a) != len(b) {
673			return false
674		}
675		seen := make(map[string]int, len(a))
676		for _, value := range a {
677			seen[value]++
678		}
679		for _, value := range b {
680			seen[value]--
681			if seen[value] < 0 {
682				return false
683			}
684		}
685		return true
686	}
