1101		sort.SliceStable(ordered, func(i, j int) bool {
1102			iCurrent := strings.EqualFold(ordered[i].ClusterHost, currentHost)
1103			jCurrent := strings.EqualFold(ordered[j].ClusterHost, currentHost)
1104			if iCurrent != jCurrent {
1105				return iCurrent
1106			}
1107			iHome := strings.EqualFold(ordered[i].Jurisdiction.Or(""), jurisdiction)
1108			jHome := strings.EqualFold(ordered[j].Jurisdiction.Or(""), jurisdiction)
1109			if currentHost == "" && iHome != jHome {
1110				return iHome
1111			}
1112			return configurePlacementLabel(ordered[i]) < configurePlacementLabel(ordered[j])
1113		})
1114		return ordered
1115	}
