1153	func configureUseMirror(ctx context.Context, outW, errW io.Writer, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) (string, error) {
1154		remotes, err := listGitRemotes(ctx, repoRoot)
1155		if err != nil {
1156			return "", err
1157		}
1158		current := ""
1159		if remotes[defaultMirrorRemote] {
1160			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1161			if err != nil {
1162				return "", fmt.Errorf("read origin remote URL: %w", err)
1163			}
1164		}
1165	
1166		forgeRemote, err := configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, defaultMirrorRemote)
1167		if err != nil {
1168			return "", err
1169		}
1170		preserve := ""
1171		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol != gitremote.ProtocolEntire {
1172			if forgeRemote == "" {
1173				preserve = availableConfigureRemoteName(remotes, defaultMirrorUpstreamRemote, mirrorCloneProviderGitHub)
1174				forgeRemote = preserve
1175			}
1176		}
1177		if forgeRemote == "" {
1178			forgeRemote = availableConfigureRemoteName(remotes, mirrorCloneProviderGitHub)
1179			forgeURL := configureGitHubForgeURL(ctx, owner, repo)
1180			if _, err := gitRunner(ctx, repoRoot, "remote", "add", forgeRemote, forgeURL); err != nil {
1181				return "", fmt.Errorf("add GitHub push remote %q: %w", forgeRemote, err)
1182			}
1183			remotes[forgeRemote] = true
1184			fmt.Fprintf(outW, "✓ Added GitHub push remote %q\n  %s\n", forgeRemote, forgeURL)
1185		}
1186	
1187		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1188		plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
1189		if err := applyMirrorRemotePlan(ctx, repoRoot, plan); err != nil {
1190			return "", err
1191		}
1192		// Report the replaced URL and where it remains reachable. The returned
1193		// forgeRemote is deliberately separate from the mirror fetch remote: config
1194		// commits must land on GitHub, never in the one-way Entire mirror.
1195		reportMirrorRemotePlan(outW, errW, plan)
1196		return forgeRemote, nil
1197	}
1198	
1199	var configureGitHubProtocol = func(ctx context.Context) string { //nolint:gochecknoglobals // test seam for the user's gh protocol preference
1200		out, err := exec.CommandContext(ctx, "gh", "config", "get", "git_protocol", "--host", "github.com").Output()
1201		if err != nil {
1202			return "https"
1203		}
1204		protocol := strings.ToLower(strings.TrimSpace(string(out)))
1205		if protocol == configureGitProtocolSSH {
1206			return protocol
1207		}
1208		return "https"
1209	}
1210	
1211	func configureGitHubForgeURL(ctx context.Context, owner, repo string) string {
1212		if configureGitHubProtocol(ctx) == configureGitProtocolSSH {
1213			return fmt.Sprintf("git@github.com:%s/%s.git", owner, repo)
1214		}
1215		return fmt.Sprintf("https://github.com/%s/%s.git", owner, repo)
1216	}
1217	
1218	func configureExistingForgeRemote(ctx context.Context, repoRoot, owner, repo string, remotes map[string]bool, exclude string) (string, error) {
1219		names := make([]string, 0, len(remotes))
1220		for name := range remotes {
1221			if name != exclude {
1222				names = append(names, name)
1223			}
1224		}
1225		sort.SliceStable(names, func(i, j int) bool {
1226			priority := func(name string) int {
1227				switch name {
1228				case mirrorCloneProviderGitHub:
1229					return 0
1230				case defaultMirrorUpstreamRemote:
1231					return 1
1232				default:
1233					return 2
1234				}
1235			}
1236			if priority(names[i]) != priority(names[j]) {
1237				return priority(names[i]) < priority(names[j])
1238			}
1239			return names[i] < names[j]
1240		})
1241		for _, name := range names {
1242			raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, name)
1243			if err != nil {
1244				return "", fmt.Errorf("read remote %q URL: %w", name, err)
1245			}
1246			info, err := gitremote.ParseURL(raw)
1247			if err == nil && info.Protocol != gitremote.ProtocolEntire && info.Forge == mirrorUseForge &&
1248				strings.EqualFold(info.Owner, owner) && strings.EqualFold(info.Repo, repo) {
1249				return name, nil
1250			}
1251		}
1252		return "", nil
1253	}
1254	
1255	func availableConfigureRemoteName(remotes map[string]bool, candidates ...string) string {
1256		for _, candidate := range candidates {
1257			if !remotes[candidate] {
1258				return candidate
1259			}
1260		}
1261		for i := 2; ; i++ {
1262			candidate := fmt.Sprintf("github-%d", i)
1263			if !remotes[candidate] {
1264				return candidate
1265			}
1266		}
1267	}
1268	
1269	// configureGitChanges returns porcelain status keyed by path. Its values retain
1270	// XY so callers can detect whether anything was already staged before the flow.
1271	func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
1272		out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
1273		if err != nil {
1274			return nil, fmt.Errorf("read git status: %w", err)
1275		}
1276		changes := make(map[string]string)
1277		for _, line := range strings.Split(out, "\n") {
1278			if len(line) < 4 {
1279				continue
1280			}
1281			path := strings.TrimSpace(line[3:])
1282			if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
1283				path = path[arrow+4:]
1284			}
1285			if path != "" {
1286				changes[path] = line[:2]
1287			}
1288		}
1289		return changes, nil
1290	}
1291	
1292	func newConfigureChanges(before, after map[string]string) []string {
1293		paths := make([]string, 0, len(after))
1294		for path := range after {
1295			if _, existed := before[path]; !existed {
1296				paths = append(paths, path)
1297			}
1298		}
1299		sort.Strings(paths)
1300		return paths
1301	}
1302	
1303	func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, branch string, protected bool, choice, forgeRemote string, now func() time.Time) error {
1304		outW := cmd.OutOrStdout()
1305		if len(generated) == 0 {
1306			fmt.Fprintln(outW, "  No new configuration changes to commit.")
1307			return nil
1308		}
1309		if len(before) != 0 {
1310			fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
1311			fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
1312			return nil
1313		}
1314	
1315		if branch == "" {
1316			return errors.New("cannot save configuration from a detached HEAD")
1317		}
1318		if protected && choice == configureSaveDirect {
1319			return fmt.Errorf("%s is protected; push to a new branch", branch)
1320		}
1321		if choice != configureSaveDirect && choice != configureSaveNewBranch {
1322			return fmt.Errorf("unknown save choice %q", choice)
1323		}
1324		if forgeRemote == "" {
1325			return errors.New("no GitHub remote available for configuration push")
1326		}
1327	
1328		pushBranch := branch
1329		switchedBranch := false
1330		if choice == configureSaveNewBranch {
1331			var err error
1332			pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, forgeRemote, now)
1333			if err != nil {
1334				return err
1335			}
1336			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1337				return fmt.Errorf("create configuration branch: %w", err)
1338			}
1339			switchedBranch = true
1340			defer func() {
1341				if switchedBranch {
1342					// Best-effort fallback for failures after branch creation. Successful
1343					// paths switch explicitly below so a restore error can be returned.
1344					if _, restoreErr := gitRunner(context.WithoutCancel(cmd.Context()), repoRoot, "switch", branch); restoreErr != nil {
1345						fmt.Fprintf(cmd.ErrOrStderr(), "warning: could not return to original branch %q: %v\n", branch, restoreErr)
1346					}
1347				}
1348			}()
1349		}
1350	
1351		args := []string{"add", "--"}
1352		args = append(args, generated...)
1353		if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1354			return fmt.Errorf("stage configuration: %w", err)
1355		}
1356		if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1357			return fmt.Errorf("commit configuration: %w", err)
1358		}
1359		sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1360		if err != nil {
1361			return fmt.Errorf("read configuration commit: %w", err)
1362		}
1363		fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1364		if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", forgeRemote, pushBranch); err != nil {
1365			return fmt.Errorf("push configuration to GitHub remote %q: %w", forgeRemote, err)
1366		}
1367		fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", forgeRemote, pushBranch)
1368		if choice == configureSaveNewBranch {
1369			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", branch); err != nil {
1370				return fmt.Errorf("return to original branch %q: %w", branch, err)
1371			}
1372			switchedBranch = false
1373			fmt.Fprintf(outW, "✓ Returned to %s\n", branch)
1374			fmt.Fprintln(outW, "  Open a trail to merge it:")
1375			fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1376		}
1377		return nil
1378	}
1379	
1380	func configureBranchHasNoUnpushedCommits(ctx context.Context, repoRoot string) bool {
1381		// @{u} is the branch's configured upstream before configure rewrites any
1382		// remotes. If it does not exist, we cannot prove a direct push is isolated to
1383		// the generated config commit, so only the new-branch action is safe.
1384		upstream, err := gitRunner(ctx, repoRoot, "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}")
1385		if err != nil || upstream == "" {
1386			return false
1387		}
1388		ahead, err := gitRunner(ctx, repoRoot, "rev-list", "--count", upstream+"..HEAD")
1389		if err != nil {
1390			return false
1391		}
1392		count, err := strconv.Atoi(strings.TrimSpace(ahead))
1393		return err == nil && count == 0
1394	}
1395	
1396	func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1397		// GitHub's branch `.protected` flag is true for *any* active ruleset rule.
1398		// A non-blocking rule such as Copilot code review therefore made ordinary
1399		// feature branches look push-protected. Inspect the effective rules instead
1400		// and only require a new branch for rules that can reject a direct update.
1401		out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/rules/branches/"+url.PathEscape(branch)).Output()
1402		if err != nil {
1403			return false, fmt.Errorf("check GitHub branch rules: %w", err)
1404		}
1405		return configureRulesBlockDirectPush(out)
1406	}
1407	
1408	func configureRulesBlockDirectPush(raw []byte) (bool, error) {
1409		var rules []struct {
1410			Type string `json:"type"`
1411		}
1412		if err := json.Unmarshal(raw, &rules); err != nil {
1413			return false, fmt.Errorf("parse GitHub branch rules: %w", err)
1414		}
1415		for _, rule := range rules {
1416			switch rule.Type {
1417			case "pull_request", "required_status_checks", "required_deployments", "required_signatures", "merge_queue", "update", "workflows":
1418				return true, nil
1419			}
1420		}
1421		return false, nil
1422	}
1423	
1424	func availableConfigureBranch(ctx context.Context, repoRoot, forgeRemote string, now func() time.Time) (string, error) {
1425		candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1426		for _, candidate := range candidates {
1427			localExists, err := configureLocalBranchExists(ctx, repoRoot, candidate)
1428			if err != nil {
1429				return "", err
1430			}
1431			if localExists {
1432				continue
1433			}
1434			remoteExists, err := configureRemoteBranchExists(ctx, repoRoot, forgeRemote, candidate)
1435			if err != nil {
1436				return "", err
1437			}
1438			if !remoteExists {
1439				return candidate, nil
1440			}
1441		}
1442		return "", errors.New("could not choose an unused configuration branch name")
1443	}
1444	
1445	func configureLocalBranchExists(ctx context.Context, repoRoot, branch string) (bool, error) {
1446		_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+branch)
1447		if err == nil {
1448			return true, nil
1449		}
1450		var exitErr *exec.ExitError
1451		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1452			return false, nil
1453		}
1454		return false, fmt.Errorf("check local configuration branch %q: %w", branch, err)
1455	}
1456	
1457	func configureRemoteBranchExists(ctx context.Context, repoRoot, forgeRemote, branch string) (bool, error) {
1458		// Query the forge directly instead of relying on remote-tracking refs, which
1459		// may be stale or absent in a fresh clone. --exit-code returns 2 when no ref
1460		// matches, and any connectivity/auth failure is treated as an error rather
1461		// than risking reuse of another user's branch.
1462		_, err := gitRunner(ctx, repoRoot, "ls-remote", "--exit-code", "--heads", forgeRemote, "refs/heads/"+branch)
1463		if err == nil {
1464			return true, nil
1465		}
1466		var exitErr *exec.ExitError
1467		if errors.As(err, &exitErr) && exitErr.ExitCode() == 2 {
1468			return false, nil
1469		}
1470		return false, fmt.Errorf("check remote configuration branch %q on %q: %w", branch, forgeRemote, err)
1471	}
